 else {drawPersonSprite(player.x,player.y,'#c05b3a','#d7a078','#38241d','down',Math.sin(t*10)*1.3,true,false);const part=n.part;const ox=part==='arm'?n.x+9:part==='leg'?n.x+6:n.x;const oy=part==='back'?n.y-1:part==='arm'?n.y-2:n.y+10;ellipse(ox,oy,12+Math.sin(t*16)*3,6+Math.sin(t*16)*2,'#ffd16a80');box(ox-5,oy-3,10,6,'#ffe19a');if(Math.floor(t*5)%2===0){box(ox+12,oy-12,3,3,'#fff0aa');box(ox-14,oy-10,3,3,'#ffb35e')}}
