 const t=a.elapsed,phase=t<1.35?0:t<2.8?1:2;const px=n.x-30,py=n.y+10;
 // little traveling ember motes
 for(let i=0;i<8;i++){const q=(t*1.35+i/8)%1;const xx=px+q*28,yy=py-11-Math.sin(q*Math.PI)*18;box(xx,yy,3,3,i%2?'#ffcf78':'#f18a48')}
