function drawHealingEffect(){
 const a=healAnim,n=people.find(p=>p.id===a.id);if(!n)return;
 const t=a.elapsed,phase=t<1.35?0:t<2.8?1:2;
 const targetX=n.part==='arm'?n.x+9:n.part==='leg'?n.x+6:n.x;
 const targetY=n.part==='back'?n.y-1:n.part==='arm'?n.y-2:n.y+10;
 // Gather warm embers around the little iron brazier, then carry that warmth to the ache.
 if(phase===0){
  const hx=n.x-22,hy=n.y+7;
  drawPersonSprite(hx-13,hy,'#c05b3a','#d7a078','#38241d','right',Math.sin(t*9)*.35,true,false);
  ellipse(hx,hy+7,17,5,'#38241e70');box(hx-10,hy+3,20,7,'#674234');box(hx-7,hy,14,4,'#b9a79a');
  ellipse(hx,hy,8+Math.sin(t*14)*2,4,'#f77e38a8');box(hx-4,hy-2,8,3,'#ffd27a');
  for(let i=0;i<4;i++){const yy=hy-8-((t*16+i*5)%18);box(hx-1+(i%2?4:-4),yy,2,4,i%2?'#ffc56c':'#f18a48')}
  for(let i=0;i<5;i++){const q=(t*1.1+i/5)%1;const xx=hx+q*22,yy=hy-8-Math.sin(q*Math.PI)*15;box(xx,yy,3,3,i%2?'#ffcf78':'#f18a48')}
 }else{
  const healerX=n.x+20,healerY=n.y+1;
  drawPersonSprite(healerX,healerY,'#c05b3a','#d7a078','#38241d','left',Math.sin(t*10)*.45,true,false);
  const pulse=12+Math.sin(t*16)*3;
  ellipse(targetX,targetY,pulse,6+Math.sin(t*16)*2,'#ffd16a80');
  // A careful, cushioned step: a warm boot briefly rests over the glowing treatment point.
  box(targetX-5,targetY-2,11,7,'#65432e');box(targetX-4,targetY-3,8,3,'#c05b3a');
  if(Math.floor(t*5)%2===0){box(targetX+12,targetY-12,3,3,'#fff0aa');box(targetX-14,targetY-10,3,3,'#ffb35e');box(targetX+1,targetY-17,2,2,'#ffc56c')}
 }
}

